  "切换会重启 Harness 并检查插件；启动失败自动恢复旧默认版本。上游原版的 Android 兼容性以实际启动检查为准。": "切り替えると Harness が再起動し、プラグインがチェックされます。起動に失敗すると元の既定バージョンに自動的に戻ります。上流のオリジナル版の Android 互換性は、実際の起動チェックの結果に準じます。",
