  "插件更新失败，已保留原版本。请检查网络后重试。": "プラグインの更新に失敗し、元のバージョンを保持しました。ネットワークを確認してから再試行してください。",
  "新版插件的依赖与当前运行时不兼容，已保留原版本": "新しいプラグインの依存関係が現在のランタイムと互換性がなく、元のバージョンを保持しました",
  "该插件没有与当前运行环境（dsh 版本）兼容的版本，已保留原版本。请升级运行环境后重试。": "このプラグインには現在の実行環境（dsh バージョン）と互換性のあるバージョンがなく、元のバージョンを保持しました。実行環境をアップデートしてから再試行してください。",
  "设备不支持安全更新所需的文件链接，已保留原版本": "このデバイスは安全な更新に必要なファイルリンクに対応しておらず、元のバージョンを保持しました",
  "上次更新尚未恢复，请重试或检查运行时": "前回の更新がまだ復元されていません。再試行するか、ランタイムを確認してください",
  "请先启用所属配置文件": "先に所属する設定ファイルを有効化してください",
  "请先停止 Harness 和 Ubuntu 终端": "先に Harness と Ubuntu ターミナルを停止してください",
  "请先安装 Ubuntu 运行时": "先に Ubuntu ランタイムをインストールしてください",
  "模型供应商格式无效": "モデルプロバイダーの形式が無効です",
  "模型凭据必须是字符串": "モデルの認証情報は文字列である必要があります",
  "模型凭据包含非法字符或长度无效": "API Key に無効な文字が含まれているか、長さが無効です",
  "同一模型凭据不能同时更新和清除": "同じモデルの認証情報を更新と削除を同時に行うことはできません",
  "运行时清单地址与 SHA-256 必须同时填写或同时留空": "ランタイムマニフェストのアドレスと SHA-256 は、両方とも入力するか両方とも空にしてください",
  "运行时清单地址长度无效": "ランタイムマニフェストのアドレス長が無効です",
  "运行时清单地址包含非法字符": "ランタイムマニフェストのアドレスに無効な文字が含まれています",
  "运行时清单地址格式无效": "ランタイムマニフェストのアドレス形式が無効です",
  "运行时清单必须使用不含凭据的 HTTPS 地址": "ランタイムマニフェストは認証情報を含まない HTTPS アドレスを使う必要があります",
  "运行时清单不能指向本机、私网或链路本地地址": "ランタイムマニフェストはこの端末、プライベートネットワーク、リンクローカルアドレスを指してはいけません",
  "运行时清单地址不能包含片段": "ランタイムマニフェストのアドレスにフラグメントを含めてはいけません",
  "清单 SHA-256 必须是 64 位小写十六进制": "マニフェストの SHA-256 は 64 文字の小文字の 16 進数である必要があります",
  "屏幕常亮设置格式无效": "画面常時点灯の設定形式が無効です",
  "终端字号必须是 11 到 24 之间的整数": "ターミナルの文字サイズは 11 から 24 の整数である必要があります",
