  "未检测到模型凭据：请先在「模型与密钥」登录 DeepSeek 账号或保存一次 API Key 再打开 Harness": "モデルの認証情報が見つかりません。「モデルとキー」で DeepSeek アカウントにログインするか API キーを保存してから、Harness を開いてください",
  "首次使用需要准备运行环境": "初回利用には実行環境の準備が必要です",
