  "安装包内置的运行环境有更新": "同梱の実行環境にアップデートがあります",
  "更新会替换 Ubuntu 运行时的系统目录。你的整个用户空间 /root（会话、模型密钥、Harness 设置、附件、技能、插件、工作区文件，以及你自己在 /root 下建的目录）都会保留；旧令牌与旧脚本不会搬回，撞名没搬回的项会留在「数据保留」里可取回。": "アップデートでは Ubuntu ランタイムのシステムディレクトリが置き換わります。ユーザー空間全体 /root（セッション、モデルキー、Harness の設定、添付ファイル、スキル、プラグイン、ワークスペースのファイル、/root 以下にご自身で作成したディレクトリ）はそのまま残ります。古いトークンと古いスクリプトは戻されません。名前が衝突して戻せなかった項目は「データ保持」に残り、取り出せます。",
  "更新会替换 Ubuntu 运行时的系统目录。你的整个用户空间 /root（会话、模型密钥、Harness 设置、附件、技能、插件、工作区文件，以及你自己在 /root 下建的目录）都会保留；终端里用 dsh plugin add 装的插件同样在插件目录里，不需要重装。旧令牌与旧脚本不会搬回，撞名没搬回的项会留在「数据保留」里可取回。": "アップデートでは Ubuntu ランタイムのシステムディレクトリが置き換わります。ユーザー空間全体 /root（セッション、モデルキー、Harness の設定、添付ファイル、スキル、プラグイン、ワークスペースのファイル、/root 以下にご自身で作成したディレクトリ）はそのまま残ります。ターミナルで dsh plugin add からインストールしたプラグインもプラグインディレクトリに残るため、再インストールは不要です。古いトークンと古いスクリプトは戻されません。名前が衝突して戻せなかった項目は「データ保持」に残り、取り出せます。",
