  "允许 HTTP 连接": "HTTP 接続を許可",
  "全部网络连接": "すべてのネットワーク接続",
  "控制 Harness 对话页面能连接哪些地址。": "Harness の会話ページが接続できるアドレスを制御します。",
  "页面只能访问本机 Harness 服务与插件市场。": "ページは端末内の Harness サービスとプラグインマーケットにのみアクセスできます。",
  "额外允许访问任意主机的明文 http（局域网自建服务）；公网 https 仍不放开。": "任意のホストへの平文 http アクセスも許可します（LAN 内の自前サービス向け）。インターネット上の https は引き続き許可しません。",
  "允许访问任意主机、任意协议，包括公网 https。": "任意のホストとプロトコル（インターネット上の https を含む）へのアクセスを許可します。",
  "放开后，页面里的内容（包括模型输出）可以把会话文本发到这些地址；明文 http 还会被同网段监听者看到。": "有効にすると、ページ内のコンテンツ（モデル出力を含む）が会話テキストをこれらのアドレスに送信できるようになります。平文の http は同じネットワーク上の第三者からも見えます。",
  "跨域 fetch 仍受对方服务器的 CORS 策略约束：能加载图片和媒体，不代表能直接调用对方的 API。": "クロスオリジンの fetch は相手サーバーの CORS ポリシーに従います。画像やメディアを読み込めても、相手の API を直接呼び出せるわけではありません。",
  "网络访问设置格式无效": "ネットワークアクセス設定の形式が無効です",
  "终端": "ターミナル",
