  "设备 Shell": "デバイス Shell",
  "运行时来源与两个入口、后台保持、悬浮球与前台服务": "ランタイムの取得元と 2 つの入口、バックグラウンド維持、フローティングボール、フォアグラウンドサービス",
  "运行时与设备 Shell": "ランタイムとデバイス Shell",
  "安装、启动、停止和重置请在「Ubuntu 运行时」中操作；Shizuku 授权在「设备 Shell 设置」中完成。": "インストール、起動、停止、リセットは「Ubuntu ランタイム」で行います。Shizuku の許可は「デバイス Shell 設定」で行ってください。",
  "运行环境使用 APK 内置的受校验版本；需要其它版本时请在 Ubuntu 运行时的版本管理中下载并切换。": "実行環境には APK に同梱された検証済みのバージョンを使用します。別のバージョンが必要な場合は、Ubuntu ランタイムのバージョン管理でダウンロードして切り替えてください。",
  "安装、启动、停止和重置请在「Ubuntu 运行时」中操作；Shizuku 授权在「设备 Shell 设置」中完成。这一页只管它们从哪来。": "インストール、起動、停止、リセットは「Ubuntu ランタイム」で行います。Shizuku の許可は「デバイス Shell 設定」で行ってください。このページはそれらの取得元だけを扱います。",
  "清单两项留空表示使用 APK 内置的运行时（官方构建即内置，可离线安装）；填写清单地址与 SHA-256 则改为从该来源下载，两项必须成对。": "両方の欄を空にすると APK に同梱されたランタイムを使用します（公式ビルドは同梱済みで、オフラインでもインストールできます）。マニフェストのアドレスと SHA-256 を入力すると、その取得元からのダウンロードに切り替わります。2 項目は必ず揃えて入力してください。",
