  "需要先授权 Shizuku，AI 才能通过它执行设备操作。请点击下方按钮打开 Shizuku 应用完成授权，返回后重新点击授权。": "AI が Shizuku 経由でデバイス操作を行うには、先に Shizuku の許可が必要です。下のボタンから Shizuku アプリを開いて許可し、アプリに戻ってから改めて許可してください。",
