  "投递区": "受け渡しエリア",
  "inbox / outbox 与访客之间的批量搬运；不会自动搬运，必须点下面的按钮。": "inbox / outbox とゲストの間で一括の受け渡しを行います。自動では受け渡されず、下のボタンを押す必要があります。",
  "用户放入（inbox）": "ユーザーが投入する場所（inbox）",
  "产物取出（outbox）": "成果物を取り出す場所（outbox）",
  "访客内挂载点": "ゲスト内のマウントポイント",
  "inbox 内文件": "inbox 内のファイル",
  "{0} 个": "{0} 個",
  "可导入的 tar：": "インポートできる tar：",
  "搬运不可用": "受け渡しは利用できません",
  "导入到工作区": "ワークスペースにインポート",
  "导出工作区": "ワークスペースをエクスポート",
  "去开启「所有文件访问」": "「すべてのファイルへのアクセス」を有効にする",
  "重新检查": "再チェック",
  "导入落点是工作区内的 {0}/ 子目录；导出固定产出 {1} + {2} + {3}（含逐条 sha256）。": "インポート先はワークスペース内の {0}/ サブディレクトリです。エクスポートでは常に {1} + {2} + {3} を出力します（各項目の sha256 付き）。",
  "存储权限：媒体读取（T1）{0} · 所有文件访问（T2）{1}。外部工作区需要 T2。": "ストレージ権限：メディアの読み取り（T1）{0} · すべてのファイルへのアクセス（T2）{1}。外部ワークスペースには T2 が必要です。",
  "inbox / outbox 不是工作区：dsh 的 write 工具写 /mnt/inbox、/mnt/outbox 会失败（实测 EACCES），这是预期行为；搬运只能走这里的按钮。": "inbox / outbox はワークスペースではありません。dsh の write ツールで /mnt/inbox や /mnt/outbox に書き込むと失敗します（実測 EACCES）。これは想定どおりの動作で、受け渡しはここのボタンからのみ行えます。",
  "最近一次导入：{0} 个条目 · {1} · manifest {2}": "直近のインポート：{0} 件 · {1} · manifest {2}",
  "最近一次导出：{0} 个条目 · {1} · manifest {2}": "直近のエクスポート：{0} 件 · {1} · manifest {2}",
  "未附带": "未添付",
  "无法读取搬运状态，请重试": "受け渡しの状態を読み取れません。再試行してください",
  "正在读取搬运状态": "受け渡し状態を読み込み中",
  "未读取": "未読み込み",
  "需要授权": "権限が必要",
  "不支持": "非対応",
  "不可写": "書き込み不可",
  "尚未授予「所有文件访问」。请到系统设置里为 DSH 手动开启；开启后回到本页会重新检查。没有该权限时只能用终端或控制台上传文件。": "「すべてのファイルへのアクセス」が許可されていません。システム設定で DSH に対して手動でオンにしてください。オンにしてからこのページに戻ると再チェックします。この権限がない場合は、ターミナルかコンソールからしかファイルをアップロードできません。",
  "当前系统不存在「所有文件访问」这一档，投递区无法启用；请改用终端或控制台上传文件。Harness 本身不受影响。": "現在のシステムには「すべてのファイルへのアクセス」の区分がないため、受け渡しエリアは有効にできません。ターミナルかコンソールからファイルをアップロードしてください。Harness 自体には影響ありません。",
  "已授予「所有文件访问」，但投递区目录仍不可读写；可能是系统限制或目录被占用。工作区与 Harness 不受影响。": "「すべてのファイルへのアクセス」は許可されていますが、受け渡しエリアのディレクトリはまだ読み書きできません。システムの制限か、ディレクトリが使用中の可能性があります。ワークスペースと Harness には影響ありません。",
  "投递区已导入工作区": "受け渡しエリアをワークスペースにインポートしました",
  "投递区文件夹已创建": "受け渡しエリアにフォルダを作成しました",
