  "当前目录条目较多，仅显示前 {0} 项；请进入子目录继续浏览。": "現在のディレクトリは項目が多いため、先頭の {0} 件のみ表示しています。サブディレクトリに入って閲覧を続けてください。",
  "无法读取当前搬运目录，请重试": "現在の受け渡しディレクトリを読み取れません。再試行してください",
  "无法读取当前目录，请重试": "現在のディレクトリを読み取れません。再試行してください",
  "导出到当前目录": "現在のディレクトリにエクスポート",
  "当前导出目标：outbox/{0}": "現在のエクスポート先：outbox/{0}",
  "inbox · 用户放入": "inbox · ユーザーが投入する場所",
  "outbox · 产物取出": "outbox · 成果物を取り出す場所",
  "外部工作区：一处浏览、建文件夹与搬运": "外部ワークスペース：閲覧、フォルダ作成、受け渡しをまとめて",
  "选择要浏览的目录": "閲覧するディレクトリを選択",
  "这里的目录都是访客能看到的「外部工作区」：手机上的文件夹挂进访客的 /mnt/user/<序号>，可以直接读写；inbox / outbox 是批量搬运通道，只能靠按钮搬运。": "ここにあるディレクトリはすべて、ゲストから見える「外部ワークスペース」です。スマートフォンのフォルダはゲストの /mnt/user/<番号> にマウントされ、直接読み書きできます。inbox / outbox は一括受け渡しのチャネルで、ボタンでしか受け渡せません。",
  "选一个目录浏览它的子目录；导入到工作区与导出工作区只对 inbox / outbox 有效。": "ディレクトリを選ぶと、そのサブディレクトリを閲覧できます。ワークスペースへのインポートとワークスペースのエクスポートは、inbox / outbox でのみ使えます。",
  "还没有挂进来的目录：在下面「目录」里添加一个手机上的目录，它会出现在这里。": "まだマウントされたディレクトリはありません。下の「ディレクトリ」でスマートフォン上のディレクトリを追加すると、ここに表示されます。",
  "挂进来的目录是实时挂载：进去之后可以直接读写，inbox / outbox 才需要先搬运一次。": "マウントされたディレクトリはリアルタイムに反映され、中では直接読み書きできます。inbox / outbox だけは先に一度受け渡しが必要です。",
