  "已安装的 Ubuntu 运行环境会被清除，其中的用户数据（会话、密钥、插件等）一并删除，终端与 Harness 会话将立即结束。": "インストール済みの Ubuntu 実行環境が削除され、その中のユーザーデータ（セッション、キー、プラグインなど）もすべて削除されます。ターミナルと Harness のセッションはすぐに終了します。",
  "请先看清上面的影响：{0} 秒后可以确认。": "上記の影響をよく確認してください。{0} 秒後に確定できます。",
  "确认后立即开始重置。": "確定するとすぐにリセットが始まります。",
