  "更新 Ubuntu 运行环境": "Ubuntu 実行環境をアップデート",
  "当前 APK 内置了新版运行环境。继续后会替换 Ubuntu 运行时的系统目录；你的整个用户空间 /root（会话、模型密钥、Harness 设置、附件、技能、插件、工作区文件，以及你自己在 /root 下建的目录）都会保留，应用设置也不受影响；旧令牌与旧脚本不会搬回，撞名没搬回的项会留在「数据保留」里可取回。": "この APK には新しい実行環境が含まれています。続行すると Ubuntu ランタイムのシステムディレクトリが置き換わります。ユーザー空間全体 /root（セッション、モデルのキー、Harness の設定、添付ファイル、スキル、プラグイン、ワークスペースのファイル、/root 以下にご自身で作成したディレクトリ）はそのまま残り、アプリの設定も影響を受けません。古いトークンと古いスクリプトは戻されません。名前が衝突して戻せなかった項目は「データ保持」に残り、取り出せます。",
  "当前 APK 内置了新版运行环境。继续后会替换 Ubuntu 运行时的系统目录；你的整个用户空间 /root 会保留（包括终端里用 dsh plugin add 装的插件），应用设置也不受影响，不需要重装任何东西；旧令牌与旧脚本不会搬回，撞名没搬回的项会留在「数据保留」里可取回。": "この APK には新しい実行環境が同梱されています。続行すると Ubuntu ランタイムのシステムディレクトリが置き換わります。ユーザー空間 /root 全体（ターミナルで dsh plugin add からインストールしたプラグインを含む）は保持され、アプリの設定にも影響はないため、何も再インストールする必要はありません。古いトークンと古いスクリプトは戻されません。名前が衝突して戻せなかった項目は「データ保持」に残り、そこから取り出せます。",
