  "设备 Shell（可选）": "デバイス Shell（任意）",
  "界面与插件": "画面とプラグイン",
  "开始使用": "はじめる",
  "跳过引导": "セットアップをスキップ",
  "步骤 ": "ステップ ",
  "本机": "この端末で",
  "已内置 Node.js、Python 3 与常用工具（busybox、jq、unzip）；gcc 等编译工具不在包内；": "Node.js、Python 3 と一般的なツール（busybox、jq、unzip）を同梱しています。gcc などのコンパイラーは含まれません。",
  "如需访问手机文件或系统操作，请配合 Shizuku 设备 Shell。": "スマートフォンのファイルにアクセスしたりシステム操作を行ったりするには、Shizuku のデバイス Shell を併用してください。",
  "首次使用需要安装 Ubuntu 运行环境（数百 MB）。应用内置的安装包可离线安装；使用在线来源时，建议通过 Wi-Fi 下载。": "初回は Ubuntu 実行環境（数百 MB）のインストールが必要です。アプリに同梱されたインストールパッケージならオフラインでインストールできます。オンラインの取得元を使う場合は Wi-Fi でのダウンロードをおすすめします。",
  "运行时下载地址不完整：请在「设置 → 后台」同时填写清单地址与 SHA-256（两者必须成对）。": "ランタイムのダウンロードアドレスが不完全です。「設定 → バックグラウンド」でマニフェストのアドレスと SHA-256 を両方入力してください（2 項目は必ず揃えて入力します）。",
  "这个安装包没带运行时下载地址：安装会先解压 APK 内置的镜像；内置镜像缺失时需要先到「设置 → 后台」填写清单地址与 SHA-256（两者必须成对）。": "このインストールパッケージにはランタイムのダウンロードアドレスが含まれていません。インストール時はまず APK に同梱されたイメージを展開します。同梱イメージがない場合は、先に「設定 → バックグラウンド」でマニフェストのアドレスと SHA-256 を入力してください（2 項目は必ず揃えて入力します）。",
  "当前状态：": "現在の状態：",
  "已安装": "インストール済み",
  " · 运行中": " · 実行中",
  "正在安装…": "インストール中…",
  "安装运行时": "ランタイムをインストール",
  "选择模型供应商并保存 API Key。密钥在本机加密保存，保存后不再显示。": "モデルプロバイダーを選んで API キーを保存します。キーはこの端末に暗号化して保存され、保存後は表示されません。",
  "可登录 DeepSeek 账号，或选择模型供应商并保存 API Key。密钥在本机加密保存，保存后不再显示。": "DeepSeek アカウントでログインするか、モデルプロバイダーを選んで API キーを保存します。キーはこの端末に暗号化して保存され、保存後は表示されません。",
  "打开 Harness 后，在侧栏「更多」菜单选择登录；登录完成后返回此页可刷新账号状态。": "Harness を開き、サイドバーの「その他」メニューからログインを選びます。ログイン後にこのページへ戻ると、アカウントの状態を更新できます。",
  "开始对话前需登录 DeepSeek 账号、保存一份 API Key，或在下方「自定义供应商」里填好第三方接口。若状态尚未同步，或凭据来自 Harness 的其他来源，可以直接打开。": "会話を始めるには、DeepSeek アカウントでログインするか、API キーを保存するか、下の「カスタムプロバイダー」にサードパーティのエンドポイントを入力してください。状態がまだ同期されていない場合や、認証情報が Harness の別の経路で設定されている場合は、そのまま開けます。",
  "用第三方接口？这步可以跳过，装好环境后在「设置 → 模型供应商 → 自定义供应商」里填 Base URL 与密钥。": "サードパーティの API を使いますか？この手順はスキップできます。環境のインストール後に「設定 → モデルプロバイダー → カスタムプロバイダー」で Base URL とキーを入力してください。",
  "开始对话前需登录 DeepSeek 账号或保存一份模型 API Key。": "会話を始める前に、DeepSeek アカウントでログインするか、モデルの API キーを保存してください。",
  "粘贴 API Key": "API キーを貼り付け",
  "DeepSeek 账号": "DeepSeek アカウント",
  "已登录，可使用账号模型": "ログイン済み。アカウントのモデルを利用できます",
  "登录 DeepSeek 账号，无需填写 API Key": "DeepSeek アカウントでログインすれば、API キーの入力は不要です",
  "登录 DeepSeek 账号后使用账号模型，无需填写 API Key": "DeepSeek アカウントでログインすると、API キーを入力せずにアカウントのモデルを利用できます",
  "登录 DeepSeek 账号": "DeepSeek アカウントでログイン",
