  "首次配置至少要保存一份模型 API Key：没有密钥时「打开 Harness」不可用。": "初回設定ではモデルの API キーを少なくとも 1 件保存してください。キーがないと「Harness を開く」は使用できません。",
  "粘贴 API Key（必填）": "API キーを貼り付け（必須）",
  "保存 API Key": "API キーを保存",
  "已配置": "設定済み",
  "未配置": "未設定",
