  "待保存": "未保存",
  "保存后清除": "保存時に削除",
  "配置": "セットアップ",
  "Shizuku 让「设备 Shell」终端以 shell 权限执行系统命令（可选，不影响 Ubuntu 终端）。": "Shizuku を使うと、「デバイス Shell」ターミナルが shell 権限でシステムコマンドを実行できます（任意。Ubuntu ターミナルには影響しません）。",
  "Shizuku 提供设备命令和文件操作能力，权限取决于其启动模式。未安装、未授权或断开时，设备工具不可用，不影响 Ubuntu 终端与 Harness。": "Shizuku はデバイスのコマンド実行とファイル操作を提供します。利用できる範囲は起動モードによって異なります。未インストール、未許可、または接続が切れている場合、デバイスツールは使えませんが、Ubuntu のターミナルと Harness には影響しません。",
  "本页分组": "このページのセクション",
  "名单内的应用才允许读取界面与执行动作。": "リスト内のアプリだけが画面の読み取りと操作の実行を許可されます。",
  "参数与规则": "パラメーターとルール",
  "取帧档位、屏幕方向、分辨率与跟随策略。": "フレーム取得の設定、画面の向き、解像度、追従動作。",
  "总开关、按应用规则与每应用参数。": "メインスイッチ、アプリごとのルール、アプリごとのパラメーター。",
  "服务状态、白名单与验证密码。": "サービスの状態、許可リスト、確認パスワード。",
  "无障碍应用自动化": "ユーザー補助によるアプリ自動化",
  "读取允许的应用界面并执行受控动作": "許可したアプリの画面を読み取り、制御された操作を実行します",
  "启用无障碍白名单限制": "ユーザー補助の許可リスト制限を有効にする",
  "关闭不会清空名单；修改后点击「保存白名单」生效，已设密码时仍需验证。": "オフにしてもリストは消えません。変更後は「許可リストを保存」を押すと反映されます。パスワードを設定している場合は確認も必要です。",
  "当前生效：白名单限制已关闭": "現在の設定：許可リスト制限はオフ",
  "当前生效：白名单限制已开启": "現在の設定：許可リスト制限はオン",
  "目标应用包名": "対象アプリのパッケージ名",
  "目标应用包名（每行一个，数量不限）": "対象アプリのパッケージ名（1 行に 1 つ、数に制限なし）",
  "当前白名单：{0}": "現在の許可リスト：{0}",
  "保存白名单": "許可リストを保存",
  "无障碍应用白名单已保存": "ユーザー補助の許可リストを保存しました",
  "开启白名单限制时仅允许列表内的应用；关闭后可操作未加入名单的普通应用。锁屏、系统设置及涉及权限、支付、验证码和密码的页面仍受保护；服务必须由你在系统无障碍设置中手动开启。": "許可リスト制限をオンにすると、リスト内のアプリだけを操作できます。オフにすると、リストにない一般のアプリも操作できます。ロック画面、システム設定、権限・支払い・確認コード・パスワードに関わる画面は引き続き保護されます。サービスはシステムのユーザー補助設定で手動で有効にする必要があります。",
  "本应用（{0}）始终在白名单中。服务重启或重新连接后也无需再次添加。": "このアプリ（{0}）は常に許可リストに含まれます。サービスの再起動や再接続の後に追加し直す必要はありません。",
  "白名单验证密码": "許可リストの確認パスワード",
  "设置后，每次修改白名单都要输入": "設定すると、許可リストを変更するたびに入力が必要になります",
  "已设置": "設定済み",
  "未设置": "未設定",
  "密码只以加盐哈希保存在设备上，不写日志、不随桥返回，界面上输入后也不保留；忘记时可用系统生物识别或锁屏密码重置，重置只清密码，白名单保留。": "パスワードはソルト付きハッシュとして端末にのみ保存され、ログにも記録されず、ブリッジ経由で返されることもありません。画面に入力した内容も保持されません。忘れた場合はシステムの生体認証または画面ロックでリセットできます。リセットではパスワードだけが消え、許可リストは残ります。",
  "当前密码": "現在のパスワード",
