  "自动化总开关已更新": "自動化の主スイッチを更新しました",
  "已紧急停止自动化": "自動化を緊急停止しました",
  "自动化只能在这里开启。总开关不是「运行中」时，规则动作会被拒绝。暂停或紧急停止不会关闭系统无障碍服务，也不会清空白名单和规则。": "自動化を開始できるのはここだけです。主スイッチが「実行中」でない場合、ルールのアクションは拒否されます。一時停止や緊急停止を行っても、システムのユーザー補助サービスはオフにならず、許可リストとルールも消えません。",
  "无障碍服务已连接": "ユーザー補助サービスは接続済み",
  "系统已开启，但服务未连接": "システムではオンですが、サービスに接続されていません",
  "系统未开启": "システムでオンになっていません",
  "：服务已运行；只有总开关显示「运行中」时，规则动作才会执行。": "：サービスは実行中です。主スイッチが「実行中」のときだけ、ルールのアクションが実行されます。",
  "：请在系统无障碍设置中手动开启（必要时先关闭再开启一次），应用无法代为开启。": "：システムのユーザー補助設定で手動でオンにしてください（必要に応じて一度オフにしてから再度オンにします）。アプリからはオンにできません。",
  "本次会话的运行记录": "このセッションの実行記録",
  "只保留无障碍服务本次运行期间的数据": "ユーザー補助サービスの今回の実行中のみ保持されます",
  "记录只在无障碍服务本次运行期间存在，服务被系统回收后会从空开始——这里为空不代表没有发生过动作。记录里只有受控码与规则标识，不含界面文字、不含截图。": "記録はユーザー補助サービスの今回の実行中だけ存在し、システムがサービスを回収すると空から始まります。ここが空でも、アクションが行われなかったとは限りません。記録に含まれるのは制御コードとルール識別子だけで、画面の文字やスクリーンショットは含まれません。",
  "运行记录读取失败，请稍后重试": "実行記録を読み取れませんでした。しばらくしてから再試行してください。",
