  "自动化规则": "自動化ルール",
  "按应用查看，逐条启用或停用": "アプリごとに表示し、ルールを個別に有効化・無効化できます",
  "规则由 AI 生成，保存前需要你确认；这里只能启用或停用规则，不能修改内容。停用规则不会删除它。": "ルールは AI が生成するため、保存前に確認が必要です。このページではルールの有効化と無効化だけができ、内容は変更できません。無効化してもルールは削除されません。",
  "白名单里还没有其他应用：先在上面加入目标应用，规则才有归属。": "許可リストに他のアプリがまだありません。ルールはアプリに紐づくため、先に上で対象アプリを追加してください。",
