  "留空表示不限制；填了就只在匹配的页面上执行。": "空欄の場合は制限なしです。入力すると、一致する画面でのみ実行されます。",
  "Activity 黑名单（每行一个正则）": "Activity 拒否リスト（1 行に 1 つの正規表現）",
  "留空表示不限制；匹配到的页面一律不执行。": "空欄にすると制限なしになります。一致した画面ではルールを一切実行しません。",
  "每应用参数": "アプリごとのパラメーター",
  "暂停与新建规则的默认值": "一時停止と新規ルールのデフォルト値",
  "先在上面选一个应用": "上でアプリを選んでください",
  "正在读取这个应用的参数": "このアプリのパラメーターを読み取り中",
  "参数读取失败，请稍后重试": "パラメーターを読み取れませんでした。しばらくしてから再試行してください。",
  "读取参数完成前不会显示输入框，也不会用默认值代替；否则保存时可能把未经确认的默认值写入设备。": "パラメーターの読み取りが完了するまで入力欄は表示されず、既定値での代用も行いません。そうでないと、保存時に未確認の既定値が端末に書き込まれるおそれがあります。",
  "参数内容不合法": "パラメーターの内容が正しくありません",
  "这份参数已经读不出来：{0}（受控码 {1}）。原生按「已暂停」处理，也不会自动删掉它；保存一次就会覆盖掉它。": "このパラメーターはすでに読み取れません：{0}（制御コード {1}）。ネイティブ側では「一時停止中」として扱われ、自動的に削除されることもありません。一度保存すると上書きされます。",
  "{0} 不在白名单里：保存参数会被原生拒绝。": "{0} は許可リストにありません。パラメーターを保存するとネイティブ側で拒否されます。",
  "当前生效：{0} · 默认动作上限 {1} · 默认冷却时间 {2} 毫秒 · 默认匹配延迟 {3} 毫秒": "現在の設定：{0} · デフォルトのアクション上限 {1} · デフォルトのクールダウン {2} ミリ秒 · デフォルトのマッチング遅延 {3} ミリ秒",
  "该应用已暂停": "このアプリは一時停止中です",
  "该应用未暂停": "このアプリは一時停止していません",
  "这三个默认值只用于新建规则表单的初值，不会改动任何一条已有规则。": "これら 3 つの既定値は、新しいルールのフォームの初期値にのみ使われます。既存のルールは一切変更されません。",
  "暂停这个应用的自动化": "このアプリの自動化を一時停止",
  "只挡规则自动求值：设备桥的单次动作（AI 明确要求的那一下）照旧走白名单与敏感窗口判定；暂停期间被丢掉的事件会计入运行记录里的「拦截原因」。": "ブロックされるのはルールの自動評価のみです。デバイスブリッジからの単発のアクション（AI が明示的に要求した 1 回）は、これまでどおり許可リストと機密ウィンドウの判定を通ります。一時停止中に破棄されたイベントは、実行記録の「ブロック理由」に計上されます。",
  "默认动作上限": "デフォルトのアクション上限",
  "默认冷却时间": "デフォルトのクールダウン",
  "默认冷却时间（毫秒）": "デフォルトのクールダウン（ミリ秒）",
  "默认匹配延迟": "デフォルトのマッチング遅延",
  "默认匹配延迟（毫秒）": "デフォルトのマッチング遅延（ミリ秒）",
  "保存参数": "パラメーターを保存",
  "恢复默认值": "デフォルトに戻す",
  "「恢复默认值」只把表单填成原生默认值，不会写盘：要生效还得再点一次「保存参数」。": "「デフォルトに戻す」はフォームにネイティブの既定値を入れるだけで、書き込みは行いません。反映するには、もう一度「パラメーターを保存」を押す必要があります。",
  "范围 {0} 到 {1}": "範囲：{0}～{1}",
  "范围 {0} 到 {1} 天": "範囲：{0}～{1} 日",
  "选择器": "セレクター",
  "选择器 {0}": "セレクター {0}",
  "选择器（多个之间必须同时满足）": "セレクター（複数指定時はすべて一致が必要）",
  "最多 {0} 个选择器；每个选择器至少要填一个条件。": "セレクターは最大 {0} 個です。各セレクターには少なくとも 1 つの条件を入力してください。",
  "添加选择器": "セレクターを追加",
  "删除选择器": "セレクターを削除",
  "删除选择器 {0}": "セレクター {0} を削除",
  "已达上限 {0} 个。": "上限の {0} 個に達しています。",
  "更多条件": "その他の条件",
  "更多条件（已填 {0} 项）": "その他の条件（{0} 項目入力済み）",
  "不限": "指定なし",
  "是": "はい",
  "否": "いいえ",
  "「不限」与「否」不是一回事：填「否」表示只匹配不具备该状态的节点。": "「指定なし」と「いいえ」は別物です。「いいえ」を選ぶと、その状態を持たないノードだけに一致します。",
  "文本": "テキスト",
  "包含文本": "テキストを含む",
