  "还没有安装运行时：安装后这里会列出当前版本与上一版本。": "ランタイムがまだインストールされていません。インストールすると、ここに現在のバージョンと前のバージョンが表示されます。",
  "已切换到上一版本": "前のバージョンに切り替えました",
  "已删除上一版本": "前のバージョンを削除しました",
  "切换到上一版本": "前のバージョンに切り替え",
  "删除上一版本": "前のバージョンを削除",
  "确认删除": "削除を確定",
  "当前使用的运行时、保留下来的上一版本，以及随安装包内置的版本。装新版本仍在运行环境页：内置更新，或填写 manifest 地址与 SHA-256。": "現在使用中のランタイム、保存されている前のバージョン、APK に同梱されたバージョンです。新しいバージョンのインストールは実行環境ページで行います。同梱版へのアップデートか、manifest の URL と SHA-256 を入力する方法があります。",
  "上一版本是上一次安装时保留下来的完整副本，切换与删除都只动它。删除后无法恢复，也不再占用磁盘。": "前のバージョンは前回のインストール時に保存された完全なコピーで、切り替えと削除はこのコピーだけに影響します。削除すると元に戻せず、ディスクも占有しなくなります。",
  "运行中不能切换版本：请先停止运行环境与 Ubuntu 终端。": "実行中はバージョンを切り替えられません。先に実行環境と Ubuntu ターミナルを停止してください。",
  "删除上一版本会永久删掉这份副本，无法撤销；当前使用的版本不受影响。": "前のバージョンを削除するとこのコピーは完全に消え、元に戻せません。現在使用中のバージョンには影響しません。",
  "现在没有可切换的上一版本：安装一次新版本后才会保留。": "切り替えられる前のバージョンはありません。新しいバージョンをインストールすると保存されます。",
  "切换到随包内置版本": "APK 同梱版に切り替え",
  "已切换到随包内置版本": "APK 同梱版に切り替えました",
  "本地版本库": "ローカルバージョンライブラリ",
  "离线保存的 dsh 运行时包（最多保留 {0} 个）。切换由本地原子解压并搬迁访客数据，不耗流量。": "オフライン保存された dsh ランタイムパッケージ（最大 {0} 個まで保持）。切り替えはローカルでアトミックに展開し、ゲストデータを移行するため、通信量はかかりません。",
  "已保存 {0} / {1}": "{0} / {1} 保存済み",
  "本地版本库暂无额外版本包。可从下方「在线可用版本」中下载。": "ローカルバージョンライブラリに追加のパッケージはありません。下の「オンラインで利用可能なバージョン」からダウンロードできます。",
