  "锁定的版本在版本库满额时不会被自动淘汰": "固定したバージョンは、ライブラリが一杯になっても自動削除されません",
  "解锁后该版本可能在版本库满额时被自动淘汰": "固定を解除すると、ライブラリが一杯になったときにこのバージョンが自動削除される場合があります",
  "已切换到指定版本": "指定したバージョンに切り替えました",
  "已从版本库删除": "バージョンライブラリから削除しました",
  "在线可用版本": "オンラインで利用可能なバージョン",
  "从官方源拉取经过适配校验的 dsh 运行时镜像。下载后存入本地版本库，可随时无网切换。": "公式ソースから、適合検証済みの dsh ランタイムイメージを取得します。ダウンロードしたものはローカルバージョンライブラリに保存され、オフラインでもいつでも切り替えられます。",
  "刷新可用版本": "利用可能なバージョンを再取得",
