  "运行时里找不到 bash": "ランタイムに bash が見つかりません",
  "重新安装或更新运行环境": "実行環境を再インストールするか、アップデートしてください",
  "运行时里找不到 node": "ランタイムに node が見つかりません",
  "找不到沙箱启动器 landlock-run": "サンドボックスランチャー landlock-run が見つかりません",
  "先点「修复运行时权限」，仍失败则重装运行时": "先に「ランタイムの権限を修復」をタップし、それでも失敗する場合はランタイムを再インストールしてください",
  "沙箱启动器没有执行位，任何被沙箱包裹的命令都无法启动": "サンドボックスランチャーに実行ビットがないため、サンドボックス経由のコマンドを一切起動できません",
  "点「修复运行时权限」即可修好，不需要重新下载运行时": "「ランタイムの権限を修復」で解決できます。ランタイムを再ダウンロードする必要はありません",
  "沙箱探测判定为不可用（内核不支持 Landlock，或启动器无法完成探测）": "サンドボックスの検査で使用不可と判定されました（カーネルが Landlock に対応していないか、ランチャーが検出を完了できません）",
  "确认系统版本后反馈此结果；沙箱不可用时 dsh 的 bash 工具无法启动": "システムのバージョンを確認したうえでこの結果を報告してください。サンドボックスが使用できない場合、dsh の bash ツールは起動できません",
  "内核只支持部分 Landlock 能力（老 ABI）": "カーネルは Landlock の一部機能のみに対応しています（古い ABI）",
  "一般仍可用；若 bash 工具仍失败请反馈此结果": "通常は引き続き使用できます。bash ツールが失敗し続ける場合は、この結果を報告してください",
  "沙箱启动器在真正执行时失败（授权根目录不存在或启动器级错误）": "サンドボックスランチャーが実際の実行時に失敗しました（許可されたルートが存在しないか、ランチャー自体のエラー）",
  "检查工作区目录是否存在，必要时重装运行时（会话、密钥、附件会保留）": "ワークスペースのディレクトリが存在するか確認し、必要に応じてランタイムを再インストールしてください（セッション、キー、添付ファイルは保持されます）",
  "被沙箱包裹的命令执行失败": "サンドボックス経由のコマンド実行に失敗しました",
  "结合运行日志查看具体报错": "実行ログと合わせて具体的なエラーを確認してください",
  "运行时里找不到 node-pty，dsh 的 bash 工具无法创建终端": "ランタイムに node-pty が見つからないため、dsh の bash ツールがターミナルを作成できません",
  "node-pty 无法加载": "node-pty を読み込めません",
  "PTY 子进程在就绪前退出——与 dsh bash 工具报的是同一现象": "PTY の子プロセスが準備完了前に終了しました。dsh の bash ツールが報告するのと同じ現象です",
  "对照上一条「沙箱内 PTY」结果：两者都失败说明问题在 PTY 层，只有它失败说明问题在沙箱": "上に表示される「サンドボックス内の PTY」の結果と比べてください。両方が失敗していれば問題は PTY 層にあり、こちらだけが失敗している場合は問題はサンドボックスにあります",
  "PTY 在限定时间内没有就绪": "PTY が制限時間内に準備完了しませんでした",
  "关闭其它应用后重试；反复出现请反馈自检结果": "他のアプリを閉じて再試行してください。繰り返し発生する場合は、セルフチェックの結果を報告してください",
  "访客数据目录不存在": "ゲストのデータディレクトリが存在しません",
  "重装运行时（会话、密钥、附件会保留）": "ランタイムを再インストールする（セッション、キー、添付ファイルは保持されます）",
  "访客数据目录不可写": "ゲストのデータディレクトリに書き込めません",
  "先确认设备剩余空间，再重装运行时": "先に端末の空き容量を確認してから、ランタイムを再インストールしてください",
  "附件目录不存在，截图等附件无法落盘": "添付ファイルディレクトリが存在しないため、スクリーンショットなどの添付ファイルを保存できません",
  "点「修复运行时权限」会自动补建该目录": "「ランタイムの権限を修復」を押すと、このディレクトリが自動で作成されます",
  "附件目录不可写——这正是「Unable to persist attachment」那类报错的成因": "添付ファイルディレクトリに書き込めません。これが「Unable to persist attachment」のようなエラーの原因です",
  "确认剩余空间；必要时重装运行时": "空き容量を確認し、必要に応じてランタイムを再インストールしてください",
  "硬链接（原子写入的前提）": "ハードリンク（アトミック書き込みの前提）",
  "本机不允许创建硬链接（同目录与跨目录都被拒绝）。dsh 的 write 工具新建文件与所有附件落盘都依赖硬链接做原子安装，因此这两条链路会失败。": "この端末ではハードリンクを作成できません（同一ディレクトリ内もディレクトリ間も拒否されます）。dsh の write ツールによるファイル作成と、すべての添付ファイルの保存は、アトミックな書き込みにハードリンクを使うため、どちらの経路も失敗します。",
  "这是运行环境（PRoot/内核策略）层面的限制，应用侧无法绕过；需要写入新文件时改用 bash 重定向或终端里的 cp/mv，图片与截图类附件在当前版本上不可用。": "これは実行環境（PRoot/カーネルポリシー）側の制限で、アプリ側では回避できません。新しいファイルを書き込む場合は bash のリダイレクトかターミナルの cp/mv を使用してください。画像やスクリーンショットの添付ファイルは現在のバージョンでは利用できません。",
  "运行时里找不到 ripgrep": "ランタイムに ripgrep が見つかりません",
  "ripgrep 没有执行位，grep / glob 工具会失败": "ripgrep に実行ビットがないため、grep / glob ツールが失敗します",
  "点「修复运行时权限」即可修好": "「ランタイムの権限を修復」で解決できます",
  "运行环境已自行停止（可能是空闲自动停止）；点「打开 Harness」会重新启动，旧会话需要重新连接。": "実行環境が自動的に停止しました（アイドルによる停止の可能性があります）。「Harness を開く」を押すと再起動します。以前のセッションは再接続が必要です。",
