  "本次没有回收任何残留。": "今回は残留物を回収しませんでした。",
  "清理详情：": "回収の詳細：",
  "仍有 {0} 份未清理，详见诊断与日志。": "{0} 件がまだ回収できていません。詳しくは診断とログを確認してください。",
  "无法读取运行时占用": "ランタイムの使用容量を取得できません",
  "清理没能完成，请稍后重试；仍然失败请查看诊断与日志。": "回収を完了できませんでした。しばらくしてから再試行してください。それでも失敗する場合は、診断とログを確認してください。",
  "目标应用副屏": "対象アプリのサブ画面",
  "在独立副屏中运行应用，通过预览页面或悬浮窗查看画面。可在此设置屏幕方向、分辨率和预览帧率。需要 Shizuku 和 Android 10 或更高版本。": "アプリを独立したサブ画面で実行し、プレビューページまたはフローティングウィンドウで画面を確認します。ここで画面の向き、解像度、プレビューのフレームレートを設定できます。Shizuku と Android 10 以上が必要です。",
  "副屏状态": "サブ画面の状態",
  "以下显示副屏的实际运行状态；无法获取的数据将显示为「未知」。": "ここにはサブ画面の実際の動作状態が表示されます。取得できないデータは「不明」と表示されます。",
  "正在读取副屏状态…": "サブ画面の状態を読み込んでいます…",
  "无法读取副屏状态": "サブ画面の状態を取得できません",
