  "副屏当前前台应用": "サブ画面で現在前面にあるアプリ",
  "副屏当前前台 Activity": "サブ画面で現在前面にある Activity",
  "前台应用信息来自副屏，无法获取时显示「未知」。": "前面アプリの情報はサブ画面のものです。取得できない場合は「不明」と表示されます。",
  "正在读取副屏设置…": "サブ画面の設定を読み込んでいます…",
  "无法读取副屏设置": "サブ画面の設定を取得できません",
  "无法读取已保存的副屏设置：{0}": "保存済みのサブ画面設定を読み込めません：{0}",
  "选择要在副屏中启动的应用。": "サブ画面で起動するアプリを選択してください。",
  "请先选择目标应用，再启动副屏。": "先に対象アプリを選択してから、サブ画面を起動してください。",
