  "分辨率": "解像度",
  "根据手机屏幕的尺寸和方向，自动设置副屏宽高与 DPI。": "スマートフォンの画面サイズと向きに応じて、サブ画面の幅、高さ、DPI を自動で設定します。",
  "自适应（按屏幕与方向计算）": "自動調整（画面と向きから計算）",
  "关闭后可手动输入宽度、高度和 DPI。": "オフにすると、幅、高さ、DPI を手動で入力できます。",
  "宽度和高度的允许范围为 {0}–{1} 像素，DPI 为 {2}–{3}；超出范围时会自动调整。": "幅と高さの許容範囲は {0}〜{1} ピクセル、DPI は {2}〜{3} です。範囲外の値は自動的に調整されます。",
  "请完整填写宽度、高度和 DPI；只填写其中一两项时，本次尺寸修改不会保存。": "幅、高さ、DPI をすべて入力してください。1 項目か 2 項目だけでは、今回のサイズ変更は保存されません。",
  "保存后将清除自定义尺寸，下次启动时使用对应屏幕方向的预设尺寸。": "保存するとカスタムサイズはクリアされ、次回起動時は画面の向きに応じたプリセットサイズが使用されます。",
  "启动时会根据设备限制缩小过大的尺寸，实际分辨率请查看上方的副屏状态。": "大きすぎるサイズは、起動時にデバイスの制限に合わせて縮小されます。実際の解像度は上のサブ画面の状態で確認してください。",
