  "结果不确定，不要重发": "結果が不確定です。再送信しないでください",
  "已跳过（任务停止）": "スキップ済み（タスク停止）",
  "输入文字": "テキスト入力",
  "滚动": "スクロール",
  "进度：已收口 {0} 步，待执行 {1} 步，共 {2} 步。": "進捗：{0} ステップ確定、{1} ステップ実行待ち、全 {2} ステップ。",
  "最近一次：{0}": "最新：{0}",
  " · 已试 {0} 次": "・{0} 回試行",
  "停止只把剩下的步骤标成跳过，已经发出去的那一步不会撤回。": "停止すると残りのステップはスキップ扱いになるだけで、すでに送信したステップは取り消されません。",
  "停止这个任务": "このタスクを停止",
  "已经停止，剩下的步骤都标成了跳过。": "停止しました。残りのステップはスキップ扱いになりました。",
  "停止失败（{0}）": "停止できませんでした（{0}）",
  "无障碍服务没有连上，现在叫不停它": "ユーザー補助サービスが接続されていないため、現在は停止できません",
  "现在没有任务可停止": "停止できるタスクはありません",
